module robotic_arm(input clk, input rst_n, input start, input signed [31:0] target_x, input signed [31:0] target_y, input [31:0] seg_length [0:7], input [2:0] num_segments, output reg signed [31:0] joint_x [0:7], output reg signed [31:0] joint_y [0:7], output reg done, output reg reachable); localparam IDLE = 3'd0, CALC_DIST = 3'd1, CHECK_REACH = 3'd2, PLACE_JOINTS = 3'd3, DONE = 3'd4; reg [2:0] state, next_state; reg [31:0] reg_target_x, reg_target_y; reg [31:0] reg_seg_length [0:7]; reg [2:0] reg_num_segments; reg [31:0] reg_distance; reg [31:0] total_length; reg [31:0] joint_x_reg [0:7], joint_y_reg [0:7]; reg [31:0] contrib_x [0:7], contrib_y [0:7]; reg [31:0] joint_acc_x, joint_acc_y; reg done_reg, reachable_reg; function [31:0] sqrt; input [31:0] x; if (x == 0) return 0; return x >> 1; endfunction always @(posedge clk or negedge rst_n) begin if (!rst_n) begin state <= IDLE; reg_target_x <= 0; reg_target_y <= 0; reg_num_segments <= 0; reg_seg_length <= 0; reg_distance <= 0; total_length <= 0; joint_x_reg <= 0; joint_y_reg <= 0; done_reg <= 0; reachable_reg <= 0; end else begin if (state == IDLE) begin if (start) begin state <= CALC_DIST; reg_target_x <= target_x; reg_target_y <= target_y; reg_num_segments <= num_segments; reg_seg_length <= seg_length; end done_reg <= 0; end else if (state == CALC_DIST) begin tx_sq = reg_target_x * reg_target_x; ty_sq = reg_target_y * reg_target_y; dist_num_sq = tx_sq + ty_sq; reg_distance <= (sqrt(dist_num_sq) >> 16) << 16; state <= CHECK_REACH; end else if (state == CHECK_REACH) begin total_length <= 0; if (reg_num_segments >=1) total_length += reg_seg_length[0]; if (reg_num_segments >=2) total_length += reg_seg_length[1]; if (reg_num_segments >=3) total_length += reg_seg_length[2]; if (reg_num_segments >=4) total_length += reg_seg_length[3]; if (reg_num_segments >=5) total_length += reg_seg_length[4]; if (reg_num_segments >=6) total_length += reg_seg_length[5]; if (reg_num_segments >=7) total_length += reg_seg_length[6]; if (reg_num_segments >=8) total_length += reg_seg_length[7]; reachable_reg = (reg_distance <= total_length) ? 1'b1 : 1'b0; if (reachable_reg) state <= PLACE_JOINTS; else state <= DONE; end else if (state == PLACE_JOINTS) begin joint_acc_x = 0; joint_acc_y = 0; for (int i=0; i<8; i++) begin if (i < reg_num_segments) begin contrib_x[i] = (reg_seg_length[i] * reg_target_x) / total_length; contrib_y[i] = (reg_seg_length[i] * reg_target_y) / total_length; end else begin contrib_x[i] = 0; contrib_y[i] = 0; end joint_acc_x = joint_acc_x + contrib_x[i]; joint_acc_y = joint_acc_y + contrib_y[i]; joint_x_reg[i] = joint_acc_x; joint_y_reg[i] = joint_acc_y; end state <= DONE; end else if (state == DONE) begin done_reg <= 1'b1; end state <= next_state; joint_x <= joint_x_reg; joint_y <= joint_y_reg; reachable <= reachable_reg; done <= done_reg; end end endmodule